before:
Complete local C example; the app itself does not execute it:
```c
#include <stdio.h>
#include <stdlib.h>

int main(void) {
 int *a = malloc(sizeof *a);
 if (a == NULL) { return 1; }
 a[0] = 4;
 int *grown = realloc(a, 2 * sizeof *a);
 if (grown == NULL) { free(a); return 1; }
 a = grown;
 a[1] = 9;
 printf("%d %d\n", a[0], a[1]);
 free(a);
}
```

